UPDATE lessons SET title='Year 3, Week 28, Lesson 4: Handwriting labelled diagrams', data=json_patch(data,'{"child_mission":"Handwriting on labelled diagrams must stay legible, with labels placed clearly and leader lines that point to the correct parts.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nHandwrite three labels for a cup diagram: rim, handle, base — with neat lines.\n\nFEEDBACK\nEach label should be readable and clearly connected to the right part.\n\nCHECK\nTiny squeezed labels can make an accurate diagram unusable.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nDraw a simple diagram of a familiar object or process stage. Add at least five handwritten labels with leader lines. Self-assess legibility and placement.\n\nWrite a short reflection describing one specific revision you made and why.","interactive_activities":null,"learning_area":"English","learning_intention":"Handwriting on labelled diagrams must stay legible, with labels placed clearly and leader lines that point to the correct parts.","lesson_number":4,"lesson_role":"Speaking and handwriting","materials":["Paper or typed answer space","Pencil"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["EN2-OLC-01","EN2-HANDW-01"],"parent_notes":"Parent: Marking guidance for the independent task: Draw a simple diagram of a familiar object or process stage. Add at least five handwritten labels with leader lines. Self-assess legibility and placement. Accept equivalent original responses that show the same s